sa_pattern.ndl:
library {
	name = "Wordpress steps"
	id = "4df968fec33732101cae1933e4013167"
	description = "Wordpress steps"
	step {
		name = "Set www directory"
		set_attr {
			"www_directory"
			"/var/www"
		}
	}
	step {
		name = "Search for wordpress dir"
		runcmd_to_var {
			cmd = concat {
				"ls -1 "
				get_attr {"www_directory"}
			}
			execution_mode = "DEFAULT"
			var_names = "wp_dir"
			parsing_strategy = delimited_parsing {
				include_lines_pattern = "wordpress"
				selected_positions = 1
			}
			if_not_found_do = nop {}
			cache_flag = 0
		}
	}
	step {
		name = "Check if wp_dir is not empty"
		if {
			condition = is_not_empty {get_attr {"wp_dir"}}
			on_true = runcmd_to_var {
				cmd = concat {
					"cat "
					get_attr {"www_directory"}
					"/"
					get_attr {"wp_dir"}
					"/wp-includes/version.php"
				}
				execution_mode = "DEFAULT"
				var_names = table {
					name = "wp_raw"
					col_names = "wp_version"
				}
				parsing_strategy = delimited_parsing {
					include_lines_pattern = "wp_version"
					exclude_lines_pattern = "@global"
					delimiters = "'"
					selected_positions = 2
				}
				if_not_found_do = nop {}
				cache_flag = 0
			}
			on_false = nop {}
		}
	}
	step {
		name = "Set config file"
		set_attr {
			"wp_raw[*].config_file"
			concat {
				get_attr {"www_directory"}
				"/"
				get_attr {"wp_dir"}
				"/wp-config.php"
			}
		}
	}
	step {
		name = "Set ip address"
		set_attr {
			"wp_raw[*].ip_address"
			get_attr {"entry_point.ip_address"}
		}
	}
	step {
		name = "Set CI fields"
		transform {
			src_table_name = "wp_raw"
			target_table_name = "x_1044869_tomek_0_cmdb_ci_u_custom_web_app"
			operation {
				set_field {
					field_name = "u_version"
					value = get_attr {"wp_raw[1].wp_version"}
				}
				set_field {
					field_name = "ip_address"
					value = get_attr {"wp_raw[1].ip_address"}
				}
				set_field {
					field_name = "name"
					value = "Wordpress"
				}
			}
		}
	}
	step {
		name = "Create connection to Apache"
		create_connection {
			connection_type = APPLICATION_FLOW
			target_ci_type = "x_1044869_tomek_0_cmdb_ci_u_custom_web_app"
			entry_point_type = "cmdb_ci_endpoint_http"
			attributes {
				attribute {
					name = "host"
					value = get_attr {"entry_point.host"}
				}
				attribute {
					name = "port"
					value = get_attr {"entry_point.port"}
				}
				attribute {
					name = "protocol"
					value = get_attr {"entry_point.protocol"}
				}
				attribute {
					name = "url"
					value = get_attr {"entry_point.url"}
				}
			}
			is_artificial = "false"
			traffic_based = "false"
		}
	}
	step {
		name = "Untitled Step"
		set_attr {
			"tmp"
			"Final step"
		}
	}
}
